const HOME_HTML = "<!doctype html>\n<html lang=\"zh-Hant\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"theme-color\" content=\"#102a43\">\n  <meta name=\"description\" content=\"CoachOS mRelay：跑完步，在 iPhone 上用 Scriptable 把 Garmin Connect 活動資料直接交給 AI 教練。\">\n  <title>CoachOS mRelay | Garmin to AI</title>\n  <style>@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');\n\n:root { --navy:#102a43; --ink:#183b56; --cream:#f8f5ed; --paper:#fffdf8; --orange:#ef8354; --mint:#cbe8db; --muted:#688096; --line:#dce5e6; }\n* { box-sizing:border-box; }\nhtml { scroll-behavior:smooth; }\nbody { margin:0; background:var(--cream); color:var(--navy); font-family:Manrope, sans-serif; line-height:1.6; }\na { color:inherit; text-decoration:none; }\n.shell { width:min(1120px, calc(100% - 40px)); margin:0 auto; }\n.hero { min-height:650px; }\n.nav { align-items:center; display:flex; justify-content:space-between; padding:28px 0; }\n.brand { align-items:center; display:flex; font-size:15px; font-weight:700; gap:10px; letter-spacing:.02em; }\n.brand b { color:var(--orange); }\n.brand-mark { align-items:center; background:var(--navy); border-radius:50%; color:var(--mint); display:inline-flex; font-family:'DM Mono', monospace; font-size:16px; height:32px; justify-content:center; width:32px; }\n.nav-link { border-bottom:1px solid var(--navy); font-size:13px; font-weight:700; padding-bottom:3px; }\n.hero-grid { align-items:center; display:grid; gap:70px; grid-template-columns:1.12fr .88fr; padding:92px 0 100px; }\n.eyebrow { color:var(--orange); font-family:'DM Mono', monospace; font-size:11px; font-weight:500; letter-spacing:.14em; margin:0 0 18px; }\nh1,h2,h3,p { margin-top:0; }\nh1 { font-size:clamp(44px, 7vw, 78px); letter-spacing:-.065em; line-height:1.04; margin-bottom:28px; max-width:700px; }\nh1 em { color:var(--orange); font-style:normal; }\n.lead { color:var(--ink); font-size:17px; max-width:580px; }\n.actions { display:flex; flex-wrap:wrap; gap:12px; margin-top:34px; }\n.button { align-items:center; border-radius:4px; display:inline-flex; font-size:13px; font-weight:800; gap:18px; justify-content:space-between; padding:15px 18px; transition:transform .2s, box-shadow .2s; }\n.button:hover { box-shadow:0 8px 20px #102a4320; transform:translateY(-2px); }\n.button-primary { background:var(--orange); color:#fff; min-width:210px; }\n.button-quiet { border:1px solid #b4c7ca; min-width:138px; }\n.microcopy { color:var(--muted); font-size:11px; margin:20px 0 0; }\n.hero-phone-wrap { align-items:center; display:flex; flex-direction:column; position:relative; }\n.hero-phone { background:#0c1824; border:9px solid #0a1722; border-radius:42px; box-shadow:18px 20px 0 var(--mint), 0 24px 50px #102a4330; max-width:286px; overflow:hidden; padding:0; position:relative; transform:rotate(3deg); width:100%; }\n.hero-phone::before { background:#152b3b; content:\"\"; height:100%; left:0; opacity:.28; pointer-events:none; position:absolute; top:0; width:100%; z-index:2; }\n.hero-phone img { display:block; height:auto; width:100%; }\n.phone-speaker { background:#0a1722; border-radius:0 0 14px 14px; height:24px; left:50%; position:absolute; top:0; transform:translateX(-50%); width:112px; z-index:3; }\n.phone-home { background:#d8e5e4; border-radius:5px; bottom:7px; height:4px; left:50%; opacity:.8; position:absolute; transform:translateX(-50%); width:72px; z-index:3; }\n.relay-badge { align-items:center; background:var(--navy); border:1px solid #55788a; box-shadow:8px 8px 0 var(--orange); color:#fff; display:flex; font-family:'DM Mono', monospace; font-size:10px; gap:9px; margin:22px -70px 0 0; padding:12px 15px; transform:rotate(-3deg); }\n.relay-badge b { font-weight:500; letter-spacing:.05em; }\n.relay-badge i { background:var(--orange); height:1px; width:26px; }\n.phone-caption { color:var(--muted); font-size:11px; margin:18px -24px 0 0; }\n.card-top { color:var(--mint); font-family:'DM Mono', monospace; font-size:11px; letter-spacing:.12em; }\n.status-dot { background:var(--orange); border-radius:50%; display:inline-block; height:8px; margin-right:8px; width:8px; }\n.route { align-items:center; display:flex; gap:14px; justify-content:center; padding:84px 0 70px; }\n.route-node { border:1px solid #7894a5; border-radius:2px; display:flex; flex-direction:column; min-width:96px; padding:12px; }\n.route-node span { color:#9bb4c2; font-family:'DM Mono', monospace; font-size:10px; }\n.route-node strong { font-size:14px; }\n.route-node.accent { border-color:var(--orange); }\n.route-node.accent span { color:var(--orange); }\n.route-line { display:flex; gap:4px; }\n.route-line i { background:var(--orange); border-radius:50%; height:4px; width:4px; }\n.card-note { border-top:1px solid #3d5c70; color:#a9c1c5; font-size:12px; padding-top:15px; }\n.signal-bar { background:var(--mint); color:var(--navy); }\n.signal-inner { align-items:center; display:flex; gap:13px; min-height:72px; }\n.signal-inner span { color:#4e7b73; font-family:'DM Mono', monospace; font-size:11px; }\n.signal-inner strong { font-size:12px; white-space:nowrap; }\n.signal-inner i { background:#719c91; height:1px; margin:0 8px; width:60px; }\n.section { padding:110px 0; }\n.section-heading { max-width:620px; }\nh2 { font-size:clamp(32px, 5vw, 52px); letter-spacing:-.06em; line-height:1.05; margin-bottom:18px; }\n.section-heading > p:last-child { color:var(--muted); font-size:15px; }\n.steps { display:grid; gap:16px; grid-template-columns:repeat(3,1fr); margin-top:54px; }\n.step-card { background:var(--paper); border:1px solid var(--line); min-height:235px; padding:25px; }\n.step-number { color:var(--orange); font-family:'DM Mono', monospace; font-size:12px; }\n.step-card h3 { font-size:21px; margin:48px 0 10px; }\n.step-card p { color:var(--muted); font-size:13px; margin:0; }\n.screenshot-section { border-top:1px solid var(--line); }\n.screenshots { display:grid; gap:34px 18px; grid-template-columns:repeat(3, 1fr); margin-top:54px; }\n.screen-card { margin:0; }\n.screen-card img { background:#131313; border:1px solid #dce5e6; border-radius:16px; box-shadow:0 12px 26px #102a4312; display:block; height:auto; width:100%; }\n.screen-card figcaption { display:flex; gap:12px; padding:15px 4px 0; }\n.screen-card figcaption > span { color:var(--orange); font-family:'DM Mono', monospace; font-size:11px; padding-top:2px; }\n.screen-card figcaption b,.screen-card figcaption small { display:block; }\n.screen-card figcaption b { font-size:14px; }\n.screen-card figcaption small { color:var(--muted); font-size:11px; line-height:1.55; margin-top:3px; }\n.split-section { display:grid; grid-template-columns:1fr 1fr; }\n.info-panel { min-height:420px; padding:48px; }\n.dark-panel { background:var(--navy); color:#fff; }\n.dark-panel .eyebrow { color:var(--mint); }\n.dark-panel p { color:#b8cbd0; max-width:380px; }\n.quote { border-left:2px solid var(--orange); color:var(--mint); font-size:14px; margin-top:80px; padding-left:16px; }\n.paper-panel { background:var(--paper); border:1px solid var(--line); }\n.feature-list { list-style:none; margin:45px 0 0; padding:0; }\n.feature-list li { align-items:flex-start; border-top:1px solid var(--line); display:flex; gap:15px; padding:17px 0; }\n.feature-list li > span { color:var(--orange); font-size:20px; }\n.feature-list b,.feature-list small { display:block; }\n.feature-list b { font-size:14px; }\n.feature-list small { color:var(--muted); font-size:12px; margin-top:3px; }\n.install-box { background:var(--orange); color:#fff; display:grid; gap:30px; grid-template-columns:.9fr 1.1fr; padding:50px; }\n.install-box .eyebrow { color:var(--navy); }\n.install-list { margin:0; padding-left:20px; }\n.install-list li { margin-bottom:8px; }\ncode { background:#102a4320; font-family:'DM Mono', monospace; font-size:.88em; padding:2px 5px; }\n.fine-print { color:#fff8; font-size:11px; grid-column:1 / -1; margin:0; }\n.footer { border-top:1px solid var(--line); display:flex; font-family:'DM Mono', monospace; font-size:10px; justify-content:space-between; padding:22px 0 30px; }\n@media (max-width:760px) {\n  .shell { width:min(100% - 28px, 540px); }\n  .hero { min-height:auto; }\n  .nav { padding:20px 0; }\n  .nav-link { display:none; }\n  .hero-grid { display:block; padding:70px 0 76px; }\n  .hero-phone-wrap { margin:62px 16px 16px 0; }\n  .hero-phone { max-width:245px; }\n  .relay-badge { margin-right:-48px; }\n  .signal-inner { gap:8px; justify-content:space-between; }\n  .signal-inner i { margin:0; width:16px; }\n  .signal-inner strong { font-size:10px; }\n  .section { padding:76px 0; }\n  .steps,.split-section { grid-template-columns:1fr; }\n  .screenshots { grid-template-columns:repeat(2, 1fr); gap:28px 12px; }\n  .screen-card img { border-radius:12px; }\n  .step-card { min-height:190px; }\n  .step-card h3 { margin-top:34px; }\n  .info-panel { min-height:360px; padding:32px 26px; }\n  .quote { margin-top:55px; }\n  .install-box { display:block; padding:30px 25px; }\n  .install-list { margin:30px 0; }\n  .fine-print { margin-top:28px; }\n  .footer { display:block; line-height:2; }\n}\n</style>\n</head>\n<body>\n  <main>\n    <section class=\"hero shell\">\n      <nav class=\"nav\" aria-label=\"主要導覽\">\n        <a class=\"brand\" href=\"#top\" aria-label=\"CoachOS mRelay 首頁\">\n          <span class=\"brand-mark\">m</span>\n          <span>CoachOS <b>mRelay</b></span>\n        </a>\n        <a class=\"nav-link\" href=\"#install\">安裝方式</a>\n      </nav>\n\n      <div class=\"hero-grid\" id=\"top\">\n        <div class=\"hero-copy\">\n          <p class=\"eyebrow\">GARMIN CONNECT × AI</p>\n          <h1>把跑步資料，<em>直接交給 AI 教練。</em></h1>\n          <p class=\"lead\">CoachOS mRelay 是一個 JavaScript 程式，搭配 iPhone／iPad 上的 Scriptable App 執行。跑完步，從 Garmin Connect 讀取活動原始內容，直接複製給 AI 教練分析。</p>\n          <div class=\"actions\">\n            <a class=\"button button-primary\" href=\"/downloads/CoachOS%20mRelay.js\" download>下載 Scriptable 腳本 <span>↓</span></a>\n            <a class=\"button button-quiet\" href=\"#how-it-works\">查看流程 <span>↘</span></a>\n          </div>\n          <p class=\"microcopy\">目前支援 iPhone／iPad + Scriptable。Android 無法直接執行此腳本。</p>\n        </div>\n        <div class=\"hero-phone-wrap\" aria-label=\"在 iPhone 上把 Garmin 活動交給 AI 教練\">\n          <div class=\"hero-phone\">\n            <div class=\"phone-speaker\"></div>\n            <img src=\"data:image/jpeg;base64,\" alt=\"iPhone 上的 Garmin Connect 活動頁面\" fetchpriority=\"high\">\n            <div class=\"phone-home\"></div>\n          </div>\n          <div class=\"relay-badge\"><span class=\"status-dot\"></span><b>GARMIN</b><i></i><b>AI 教練</b></div>\n          <p class=\"phone-caption\">跑完一場，手機就是資料接力站。</p>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"signal-bar\">\n      <div class=\"shell signal-inner\">\n        <span>01</span><strong>開啟活動</strong><i></i>\n        <span>02</span><strong>切換分頁</strong><i></i>\n        <span>03</span><strong>貼給 AI</strong>\n      </div>\n    </section>\n\n    <section class=\"section shell\" id=\"how-it-works\">\n      <div class=\"section-heading\">\n        <p class=\"eyebrow\">HOW IT WORKS</p>\n        <h2>三步，完成一次資料接力。</h2>\n        <p>你只需要在 Garmin Connect 裡做一次選擇，其餘由 mRelay 整理成 AI 看得懂的原始內容。</p>\n      </div>\n      <div class=\"steps\">\n        <article class=\"step-card\"><span class=\"step-number\">01</span><h3>選活動</h3><p>執行腳本後，程式會開啟 Garmin Connect 活動列表。登入並點進要分析的活動。</p></article>\n        <article class=\"step-card\"><span class=\"step-number\">02</span><h3>選第二分頁</h3><p>先保留「數據」分頁，再切換到「計圈」或「間歇訓練」分頁，等表格載入後關閉。</p></article>\n        <article class=\"step-card\"><span class=\"step-number\">03</span><h3>貼給 AI</h3><p>完整原始內容會自動複製到剪貼簿。開啟 ChatGPT、Claude 或 Gemini，貼上即可。</p></article>\n      </div>\n    </section>\n\n    <section class=\"section screenshot-section shell\" id=\"screenshots\">\n      <div class=\"section-heading\">\n        <p class=\"eyebrow\">ON YOUR IPHONE</p>\n        <h2>照著畫面走，就不會迷路。</h2>\n        <p>以下截圖是實際操作順序。每次關閉 Garmin WebView 前，先確認目前停在正確的分頁。</p>\n      </div>\n      <div class=\"screenshots\">\n        <figure class=\"screen-card\">\n          <img src=\"data:image/jpeg;base64,\" alt=\"Scriptable 中的 CoachOS mRelay 啟動提示\" loading=\"lazy\">\n          <figcaption><span>01</span><div><b>啟動 mRelay</b><small>在 Scriptable 點擊 CoachOS mRelay，按「開啟 Garmin」。</small></div></figcaption>\n        </figure>\n        <figure class=\"screen-card\">\n          <img src=\"data:image/jpeg;base64,\" alt=\"Garmin Connect 活動列表\" loading=\"lazy\">\n          <figcaption><span>02</span><div><b>選擇活動</b><small>在活動列表點進要分析的跑步活動。</small></div></figcaption>\n        </figure>\n        <figure class=\"screen-card\">\n          <img src=\"data:image/jpeg;base64,\" alt=\"Garmin Connect 活動數據頁\" loading=\"lazy\">\n          <figcaption><span>03</span><div><b>保留數據分頁</b><small>等摘要內容載入完成，再關閉 Garmin WebView。</small></div></figcaption>\n        </figure>\n        <figure class=\"screen-card\">\n          <img src=\"data:image/jpeg;base64,\" alt=\"Scriptable 提示切換到計圈或間歇訓練分頁\" loading=\"lazy\">\n          <figcaption><span>04</span><div><b>準備第二次讀取</b><small>按下「開啟計圈／間歇訓練」，回到同一個活動頁。</small></div></figcaption>\n        </figure>\n        <figure class=\"screen-card\">\n          <img src=\"data:image/jpeg;base64,\" alt=\"Garmin Connect 間歇訓練分頁表格\" loading=\"lazy\">\n          <figcaption><span>05</span><div><b>切換資料分頁</b><small>選擇「計圈」或「間歇訓練」，不要選第三個「區段」。</small></div></figcaption>\n        </figure>\n        <figure class=\"screen-card\">\n          <img src=\"data:image/jpeg;base64,\" alt=\"CoachOS mRelay 完成並複製到剪貼簿\" loading=\"lazy\">\n          <figcaption><span>06</span><div><b>貼給 AI</b><small>看到完成提示後，開啟常用 AI，進入 Project／對話並貼上。</small></div></figcaption>\n        </figure>\n      </div>\n    </section>\n\n    <section class=\"split-section shell\">\n      <div class=\"info-panel dark-panel\">\n        <p class=\"eyebrow\">WHY RAW DOM</p>\n        <h2>不猜欄位，保留現場。</h2>\n        <p>Garmin Connect 是動態渲染的 SPA。mRelay 在你關閉 WebView 後讀取畫面內容，不依賴 Garmin API，也不把欄位位置寫死。</p>\n        <div class=\"quote\">「讓 AI 讀完整上下文，而不是只讀幾個數字。」</div>\n      </div>\n      <div class=\"info-panel paper-panel\">\n        <p class=\"eyebrow\">WHAT AI GETS</p>\n        <ul class=\"feature-list\">\n          <li><span>↗</span><div><b>數據分頁</b><small>活動摘要、心率、功率、訓練效果、主觀感受</small></div></li>\n          <li><span>↗</span><div><b>計圈／間歇訓練分頁</b><small>各段時間、距離、配速、心率與跑步動態</small></div></li>\n          <li><span>↗</span><div><b>日期上下文</b><small>保留 Garmin 顯示的今天、昨天、星期幾或完整日期</small></div></li>\n        </ul>\n      </div>\n    </section>\n\n    <section class=\"section shell\" id=\"install\">\n      <div class=\"install-box\">\n        <div>\n          <p class=\"eyebrow\">INSTALL ON IOS</p>\n          <h2>從網站下載，放進 Scriptable。</h2>\n        </div>\n        <ol class=\"install-list\">\n          <li>安裝 <b>Scriptable</b> App。</li>\n          <li>點擊網站上的「下載 Scriptable 腳本」。</li>\n          <li>在「檔案」App 將 <code>CoachOS mRelay.js</code> 儲存到 <code>iCloud Drive／Scriptable</code>。</li>\n          <li>回到 Scriptable，在 Scripts 清單執行腳本。</li>\n        </ol>\n        <p class=\"fine-print\">第一次使用時，請在 WebView 中登入 Garmin Connect。腳本不會把帳號密碼、Cookie 或 Token 寫入程式。</p>\n      </div>\n    </section>\n  </main>\n\n  <footer class=\"footer shell\">\n    <span>CoachOS mRelay</span>\n    <span>JavaScript · Scriptable · Garmin Connect</span>\n  </footer>\n</body>\n</html>\n";
const DOWNLOAD_JS = "// Variables used by Scriptable.\n// These must be at the very top of the file. Do not edit.\n// icon-color: deep-blue; icon-glyph: magic;\n// ============================================================\n// 🏃‍♂️ CoachOS mRelay for Scriptable\n// 從 Garmin Connect 頁面 DOM 讀取資料，對齊 Excel v1.1 格式\n// ============================================================\n\n// Keychain keys（跨次儲存個人設定）\nconst K_MAXHR  = 'coachOS_maxHR';\nconst K_CP     = 'coachOS_cp';\nconst K_SHOES  = 'coachOS_shoes';\nconst K_COURSE = 'coachOS_courseType';\nconst K_GOAL   = 'coachOS_goal';\n\nfunction kGet(key, def) {\n  return Keychain.contains(key) ? Keychain.get(key) : (def || '');\n}\nfunction kSet(key, val) { if (val) Keychain.set(key, String(val)); }\n\nfunction extractActivityId(url) {\n  const m = url.match(/\\/activity\\/(\\d+)/);\n  return m ? m[1] : null;\n}\n\nfunction inferCourseType(name) {\n  const s = String(name || '').toLowerCase();\n  if (/interval|tempo|threshold|fartlek|speed|repeats/.test(s)) return 'Quality Run';\n  if (/long|lsd/.test(s)) return 'Long Run';\n  if (/recovery|easy|eazy|jog|warm/.test(s)) return 'Easy Run';\n  if (/race|marathon|half|10k|5k/.test(s)) return 'Race';\n  return '';\n}\n\nfunction inferGoal(courseType) {\n  switch (courseType) {\n    case 'Easy Run':\n      return 'Aerobic Base';\n    case 'Long Run':\n      return 'Aerobic Endurance';\n    case 'Quality Run':\n      return 'Threshold / VO2max';\n    case 'Race':\n      return 'Race Specific';\n    default:\n      return '';\n  }\n}\n\n// ============================================================\n// 解析 DOM innerText\n// ============================================================\n\nfunction parseActivity(text) {\n  const d = {};\n  const lines = String(text || '').split('\\n').map(s => s.trim()).filter(Boolean);\n  const pad = n => String(n).padStart(2, '0');\n  const now = new Date();\n  const fmt = (dt) => `${dt.getFullYear()}-${pad(dt.getMonth()+1)}-${pad(dt.getDate())}`;\n  const weekdays = {\n    '星期日': 0, '星期天': 0, '星期一': 1, '星期二': 2, '星期三': 3,\n    '星期四': 4, '星期五': 5, '星期六': 6,\n  };\n  const parseDisplayDate = function() {\n    const firstMatch = text.match(/(?:今天|昨天|星期[日天一二三四五六])(?:\\s*@|\\s+@|\\s)/);\n    if (firstMatch) {\n      const label = firstMatch[0].replace(/\\s*@.*$/, '').trim();\n      if (label === '今天') return fmt(now);\n      if (label === '昨天') {\n        const y = new Date(now);\n        y.setDate(y.getDate() - 1);\n        return fmt(y);\n      }\n      const m = label.match(/星期[日天一二三四五六]/);\n      if (m) {\n        const target = weekdays[m[0]];\n        const d0 = new Date(now);\n        for (let i = 0; i < 7; i++) {\n          if (d0.getDay() === target) return fmt(d0);\n          d0.setDate(d0.getDate() - 1);\n        }\n      }\n    }\n\n    const explicit = text.match(/(\\d{4})[\\/.-](\\d{1,2})[\\/.-](\\d{1,2})/);\n    if (explicit) return `${explicit[1]}-${pad(explicit[2])}-${pad(explicit[3])}`;\n\n    const monthDay = text.match(/(\\d{1,2})[\\/.-](\\d{1,2})/);\n    if (monthDay) {\n      const candidate = new Date(now.getFullYear(), parseInt(monthDay[1], 10) - 1, parseInt(monthDay[2], 10));\n      return fmt(candidate);\n    }\n\n    return fmt(now);\n  };\n  d.date = parseDisplayDate();\n\n  const nameM = text.match(/[AP]M\\s*\\n+([^\\n]+)\\n+活動:/);\n  d.name = nameM ? nameM[1].trim() : null;\n\n  const timeM = text.match(/今天 @ (\\d+:\\d+ [AP]M)/);\n  d.startTime = timeM ? timeM[1] : null;\n\n  const rx  = (re) => { const r = text.match(re); return r ? r[1] : null; };\n  const rxf = (re) => { const v = rx(re); return v ? parseFloat(v) : null; };\n  const rxi = (re) => { const v = rx(re); return v ? parseInt(v, 10) : null; };\n  const pair = function(patterns) {\n    for (const re of patterns) {\n      const m = text.match(re);\n      if (m && m[1] != null) return m[1];\n    }\n    return null;\n  };\n  const findAfter = function(labels, valueRe, maxLookahead) {\n    const labelList = Array.isArray(labels) ? labels : [labels];\n    for (const label of labelList) {\n      const idx = lines.findIndex(line => line === label || line.startsWith(label + '：') || line.startsWith(label + ':'));\n      if (idx < 0) continue;\n      const end = Math.min(lines.length, idx + 1 + (maxLookahead || 6));\n      for (let i = idx + 1; i < end; i++) {\n        const v = lines[i];\n        if (!v) continue;\n        if (!valueRe) return v;\n        const m = v.match(valueRe);\n        if (m) return m[1];\n      }\n    }\n    return null;\n  };\n  const findBefore = function(label) {\n    const idx = lines.findIndex(line => line === label || line.startsWith(label + '：') || line.startsWith(label + ':'));\n    if (idx <= 0) return null;\n    const v = String(lines[idx - 1] || '').trim();\n    if (!v || v === '?' || v === '？') return null;\n    return v;\n  };\n  const findNearNumber = function(labels, min, max, maxLookahead) {\n    const labelList = Array.isArray(labels) ? labels : [labels];\n    for (const label of labelList) {\n      const idx = lines.findIndex(line => line === label || line.startsWith(label + '：') || line.startsWith(label + ':'));\n      if (idx < 0) continue;\n      const end = Math.min(lines.length, idx + 1 + (maxLookahead || 6));\n      for (let i = idx + 1; i < end; i++) {\n        const v = lines[i];\n        if (!v) continue;\n        const m = v.match(/^([\\d]+(?:\\.[\\d]+)?)$/);\n        if (!m) continue;\n        const n = parseFloat(m[1]);\n        if (Number.isFinite(n) && n >= min && n <= max) return n;\n      }\n    }\n    return null;\n  };\n  const findNearWithUnit = function(labels, unitRe, min, max, maxLookahead) {\n    const labelList = Array.isArray(labels) ? labels : [labels];\n    for (const label of labelList) {\n      const idx = lines.findIndex(line => line === label || line.startsWith(label + '：') || line.startsWith(label + ':'));\n      if (idx < 0) continue;\n      const end = Math.min(lines.length, idx + 1 + (maxLookahead || 6));\n      for (let i = idx + 1; i < end; i++) {\n        const v = lines[i];\n        if (!v) continue;\n        const m = v.match(/^([\\d]+(?:\\.[\\d]+)?)\\s*([^\\d\\s]+)?$/);\n        if (!m) continue;\n        const n = parseFloat(m[1]);\n        const unit = m[2] || '';\n        if (Number.isFinite(n) && n >= min && n <= max && (!unitRe || unitRe.test(unit))) return n;\n      }\n    }\n    return null;\n  };\n  const toInt = function(v) {\n    const n = parseInt(v, 10);\n    return Number.isFinite(n) ? n : null;\n  };\n  const toFloat = function(v) {\n    const n = parseFloat(v);\n    return Number.isFinite(n) ? n : null;\n  };\n\n  d.distance = toFloat(pair([\n    /([\\d.]+)\\s*公里\\s*\\n(?:距離|實際距離)/,\n    /(?:距離|實際距離)\\s*\\n\\s*([\\d.]+)\\s*公里/,\n  ]) || findAfter(['距離', '實際距離'], /^([\\d.]+)\\s*公里$/, 4));\n  d.duration = pair([\n    /([\\d:]+)\\s*\\n(?:時間|計時)/,\n    /(?:時間|計時)\\s*\\n\\s*([\\d:]+)/,\n  ]) || findAfter(['時間', '計時'], /^([\\d:]+)$/, 4);\n  d.movingTime = pair([\n    /([\\d:]+)\\s*\\n移動時間/,\n    /移動時間\\s*\\n\\s*([\\d:]+)/,\n  ]) || findAfter('移動時間', /^([\\d:]+)$/, 4);\n  d.avgPace = pair([\n    /([\\d:]+)\\s*\\/(?:公里|km)\\s*\\n平均配速/,\n    /平均配速\\s*\\n\\s*([\\d:]+)\\s*\\/(?:公里|km)/,\n  ]) || findAfter('平均配速', /^([\\d:]+)\\s*\\/(?:公里|km)$/, 4);\n  d.bestPace = pair([\n    /([\\d:]+)\\s*\\/(?:公里|km)\\s*\\n最佳配速/,\n    /最佳配速\\s*\\n\\s*([\\d:]+)\\s*\\/(?:公里|km)/,\n  ]) || findAfter('最佳配速', /^([\\d:]+)\\s*\\/(?:公里|km)$/, 4);\n  d.gap = pair([\n    /([\\d:]+)\\s*\\/(?:公里|km)\\s*\\n(?:平均坡度校正配速|平均坡度修正配速)/,\n    /(?:平均坡度校正配速|平均坡度修正配速)\\s*\\n\\s*([\\d:]+)\\s*\\/(?:公里|km)/,\n  ]) || findAfter(['平均坡度校正配速', '平均坡度修正配速'], /^([\\d:]+)\\s*\\/(?:公里|km)$/, 4);\n  d.avgHR = toInt(findBefore('平均心率') || rxi([\n    /([\\d]+)\\s*bpm\\s*\\n平均心率/,\n    /平均心率\\s*\\n\\s*([\\d]+)\\s*bpm/,\n  ]) || findAfter('平均心率', /^([\\d]+)\\s*bpm$/, 4)) || null;\n  d.maxHR = toInt(findBefore('最大心率') || rxi([\n    /([\\d]+)\\s*bpm\\s*\\n最大心率/,\n    /最大心率\\s*\\n\\s*([\\d]+)\\s*bpm/,\n  ]) || findAfter('最大心率', /^([\\d]+)\\s*bpm$/, 4)) || null;\n  d.calories = toInt(findBefore('總消耗卡路里') || findBefore('消耗熱量') || rxi([\n    /([\\d]+)\\s*\\n總消耗卡路里/,\n    /總消耗卡路里\\s*\\n\\s*([\\d]+)/,\n  ]) || findAfter('總消耗卡路里', /^([\\d]+)$/, 4)) || null;\n  d.elevGain = toInt(findBefore('總爬升') || rxi([\n    /([\\d]+)\\s*(?:公尺|m)\\s*\\n總爬升/,\n    /總爬升\\s*\\n\\s*([\\d]+)\\s*(?:公尺|m)/,\n  ]) || findAfter('總爬升', /^([\\d]+)\\s*(?:公尺|m)$/, 4)) || null;\n  d.elevDesc = findNearNumber('總下降', 0, 20000, 4);\n\n  // 跑步動態\n  d.cadence  = toInt(rxi([\n    /([\\d]+)\\s*每分鐘步數\\s*\\n平均步頻/,\n    /平均步頻\\s*\\n\\s*([\\d]+)\\s*spm/,\n  ]) || findAfter('平均步頻', /^([\\d]+)\\s*spm$/, 4)) || null;\n  d.strideM  = rxf([\n    /([\\d.]+)\\s*公尺\\s*\\n平均步幅/,\n    /平均步幅\\s*\\n\\s*([\\d.]+)\\s*mm/,\n  ]) || (function() {\n    const v = findAfter('平均步幅', /^([\\d.]+)\\s*mm$/, 4);\n    return v ? parseFloat(v) / 1000 : null;\n  })();\n  d.gct      = toFloat(rxf([\n    /([\\d.]+)\\s*(?:亳秒|毫秒|ms)\\s*\\n平均觸地時間/,\n    /平均觸地時間\\s*\\(GCT\\)\\s*\\n\\s*([\\d.]+)\\s*(?:亳秒|毫秒|ms)/,\n  ]) || findAfter('平均觸地時間', /^([\\d.]+)\\s*(?:亳秒|毫秒|ms)$/, 4)) || null;\n  d.vo       = rxf([\n    /([\\d.]+)\\s*cm\\s*\\n平均垂直振幅/,\n    /平均垂直振幅\\s*\\n\\s*([\\d.]+)\\s*mm/,\n  ]) || (function() {\n    const v = findAfter('平均垂直振幅', /^([\\d.]+)\\s*mm$/, 4);\n    return v ? parseFloat(v) / 10 : null;\n  })();\n  d.vr       = toFloat(rxf([\n    /([\\d.]+)\\s*%\\s*\\n平均移動效率/,\n    /平均垂直比\\s*\\n\\s*([\\d.]+)\\s*%/,\n  ]) || findAfter('平均垂直比', /^([\\d.]+)\\s*%$/, 4)) || null;\n  d.avgPower = toInt(rxi([\n    /([\\d]+)\\s*瓦\\s*\\n平均功率/,\n    /平均功率\\s*\\n\\s*([\\d]+)\\s*W/,\n  ]) || findAfter('平均功率', /^([\\d]+)\\s*W$/, 4)) || null;\n  d.maxPower = toInt(rxi([\n    /([\\d]+)\\s*瓦\\s*\\n最大功率/,\n    /最大功率\\s*\\n\\s*([\\d]+)\\s*W/,\n  ]) || findAfter('最大功率', /^([\\d]+)\\s*W$/, 4)) || null;\n\n  // 訓練效果\n  d.teAero    = toFloat(rxf([\n    /([\\d.]+)\\s*影響\\s*\\n有氧/,\n    /有氧訓練效果\\s*\\n\\s*([\\d.]+)/,\n  ]) || findAfter('有氧訓練效果', /^([\\d.]+)$/, 4)) || null;\n  d.teAna     = toFloat(rxf([\n    /([\\d.]+)\\s*(?:影響|維持效果)\\s*\\n無氧/,\n    /無氧訓練效果\\s*\\n\\s*([\\d.]+)/,\n  ]) || findAfter('無氧訓練效果', /^([\\d.]+)$/, 4)) || null;\n  d.teBenefit = pair([\n    /([^\\n]+)\\n主要益處/,\n    /主要益處\\s*\\n\\s*([^\\n]+)/,\n  ]) || findAfter('主要益處', /^([^\\n]+)$/, 4);\n  d.load      = toInt(rxi([\n    /([\\d]+)\\n運動負荷/,\n    /訓練負荷\\s*\\n\\s*([\\d]+)/,\n  ]) || findAfter('訓練負荷', /^([\\d]+)$/, 4)) || null;\n  d.perf      = toInt(rxi([\n    /([\\d]+)%(?:良好|普通|差勁|優異)/,\n    /執行分數\\s*\\n\\s*([\\d]+)%/,\n  ]) || findAfter('執行分數', /^([\\d]+)%$/, 4)) || null;\n\n  // 體力\n  d.stamStart = findNearNumber(['起始體力', '起始上限'], 0, 100, 4);\n  d.stamEnd   = findNearNumber(['結束體力', '結束上限'], 0, 100, 4);\n\n  // 手錶感測溫度\n  d.watchTemp = toFloat(rxf([\n    /([\\d.]+)\\s*°C\\s*\\n平均溫度/,\n    /平均溫度\\s*\\n\\s*([\\d.]+)\\s*°C/,\n  ]) || findAfter('平均溫度', /^([\\d.]+)\\s*°C$/, 4)) || null;\n\n  // EF\n  if (d.avgPace && d.avgHR) {\n    const parts = d.avgPace.split(':');\n    const paceSec = parseInt(parts[0], 10) * 60 + parseInt(parts[1], 10);\n    const speedMpMin = 1000 / paceSec * 60;\n    d.ef = (speedMpMin / d.avgHR).toFixed(3);\n  }\n\n  return d;\n}\n\n// ============================================================\n// 解析每公里資料（best-effort）\n// ============================================================\n\nfunction parseLaps(text) {\n  const laps = [];\n  const tableSection = text.match(/每公里([\\s\\S]{0,5000}?)(?:圈次|間歇|備註|$)/);\n  if (!tableSection) return laps;\n\n  const rows = tableSection[1].trim().split('\\n').map(function(s) { return s.trim(); }).filter(Boolean);\n  let i = 0;\n  while (i < rows.length - 2) {\n    const lapNum = parseInt(rows[i], 10);\n    if (!isNaN(lapNum) && lapNum > 0 && lapNum <= 50) {\n      const paceM = rows[i+1] ? rows[i+1].match(/^(\\d+:\\d+)$/) : null;\n      const hrM   = rows[i+2] ? rows[i+2].match(/^(\\d{2,3})$/) : null;\n      if (paceM && hrM) {\n        laps.push({ km: lapNum, pace: paceM[1], hr: parseInt(hrM[1], 10) });\n        i += 3;\n        continue;\n      }\n    }\n    i++;\n  }\n  return laps;\n}\n\nfunction calcFromLaps(laps) {\n  if (!laps || laps.length < 2) return { hrDrift: null, cv: null };\n\n  const half = Math.floor(laps.length / 2);\n  const avg = function(arr) { return arr.reduce(function(s, v) { return s + v; }, 0) / arr.length; };\n\n  const hrs = laps.map(function(l) { return l.hr; });\n  const firstHR = avg(hrs.slice(0, half));\n  const lastHR  = avg(hrs.slice(half));\n  const hrDrift = (lastHR - firstHR) / firstHR * 100;\n\n  const pacesSec = laps.map(function(l) {\n    const parts = l.pace.split(':');\n    return parseInt(parts[0], 10) * 60 + parseInt(parts[1], 10);\n  });\n  const avgP = avg(pacesSec);\n  const sd   = Math.sqrt(avg(pacesSec.map(function(v) { return Math.pow(v - avgP, 2); })));\n  const cv   = sd / avgP * 100;\n\n  return {\n    hrDrift: (hrDrift >= 0 ? '+' : '') + hrDrift.toFixed(1) + '%',\n    cv: cv.toFixed(1) + '%',\n  };\n}\n\n// ============================================================\n// 天氣（wttr.in）\n// ============================================================\n\nasync function fetchWeather(location) {\n  if (!location || !location.trim()) return null;\n  try {\n    const loc = encodeURIComponent(location.trim());\n    const req = new Request('https://wttr.in/' + loc + '?format=j1');\n    req.timeoutInterval = 8;\n    const data = await req.loadJSON();\n    const c = data && data.current_condition && data.current_condition[0];\n    if (!c) return null;\n    const descArr = (c.lang_zh && c.lang_zh.length) ? c.lang_zh : c.weatherDesc;\n    const desc = (descArr && descArr[0] && descArr[0].value) ? descArr[0].value : 'N/A';\n    return {\n      desc:    desc,\n      temp:    c.temp_C + '°C',\n      humidity: c.humidity + '%',\n      windDir: c.winddir16Point || 'N/A',\n      windKmh: c.windspeedKmph + ' km/h',\n    };\n  } catch(e) {\n    return null;\n  }\n}\n\nfunction sleep(ms) {\n  return new Promise(resolve => {\n    const timer = new Timer();\n    timer.timeInterval = ms / 1000;\n    timer.repeats = false;\n    timer.schedule(() => resolve());\n  });\n}\n\nfunction mergeActivityDetails(d, activityJson, detailJson) {\n  const act = activityJson || {};\n  const det = detailJson || {};\n\n  const pickNum = function(v) {\n    const n = Number(v);\n    return Number.isFinite(n) ? n : null;\n  };\n\n  const pickFrom = function(obj, paths) {\n    for (const path of paths) {\n      let cur = obj;\n      let ok = true;\n      for (const key of path) {\n        if (cur && Object.prototype.hasOwnProperty.call(cur, key)) {\n          cur = cur[key];\n        } else {\n          ok = false;\n          break;\n        }\n      }\n      if (ok && cur !== undefined && cur !== null && cur !== '') return cur;\n    }\n    return null;\n  };\n\n  const assignIfMissing = function(key, val) {\n    if (d[key] == null && val != null && val !== '') d[key] = val;\n  };\n\n  const firstValidNumber = function() {\n    for (let i = 0; i < arguments.length; i++) {\n      const v = arguments[i];\n      if (v == null || v === '') continue;\n      const n = Number(v);\n      if (Number.isFinite(n) && n > 0) return n;\n    }\n    return null;\n  };\n\n  assignIfMissing('distance', firstValidNumber(pickFrom(act, [['distance'], ['summary', 'distance']]), pickFrom(det, [['distance'], ['summary', 'distance']])));\n  assignIfMissing('duration', pickFrom(act, [['duration'], ['movingTime'], ['elapsedDuration']]) || pickFrom(det, [['duration'], ['movingTime'], ['elapsedDuration']]));\n  assignIfMissing('movingTime', pickFrom(act, [['movingTime']]) || pickFrom(det, [['movingTime']]));\n  assignIfMissing('avgPace', pickFrom(act, [['avgPace'], ['averagePace'], ['pace']]) || pickFrom(det, [['avgPace'], ['averagePace'], ['pace']]));\n  assignIfMissing('bestPace', pickFrom(act, [['bestPace'], ['maxPace']]) || pickFrom(det, [['bestPace'], ['maxPace']]));\n  assignIfMissing('gap', pickFrom(act, [['gap'], ['gradeAdjustedPace']]) || pickFrom(det, [['gap'], ['gradeAdjustedPace']]));\n  assignIfMissing('avgHR', firstValidNumber(pickNum(pickFrom(act, [['averageHR'], ['avgHR'], ['averageHeartRate'], ['avgHeartRate']])), pickNum(pickFrom(det, [['averageHR'], ['avgHR'], ['averageHeartRate'], ['avgHeartRate']]))));\n  assignIfMissing('maxHR', firstValidNumber(pickNum(pickFrom(act, [['maxHR'], ['maxHeartRate']])), pickNum(pickFrom(det, [['maxHR'], ['maxHeartRate']]))));\n  assignIfMissing('calories', firstValidNumber(pickNum(pickFrom(act, [['calories'], ['totalCalories'], ['activeCalories']])), pickNum(pickFrom(det, [['calories'], ['totalCalories'], ['activeCalories']]))));\n  assignIfMissing('elevGain', firstValidNumber(pickNum(pickFrom(act, [['elevGain'], ['totalElevationGain'], ['elevationGain']])), pickNum(pickFrom(det, [['elevGain'], ['totalElevationGain'], ['elevationGain']]))));\n  assignIfMissing('cadence', firstValidNumber(pickNum(pickFrom(act, [['averageCadence'], ['cadence']])), pickNum(pickFrom(det, [['averageCadence'], ['cadence']]))));\n  assignIfMissing('avgPower', firstValidNumber(pickNum(pickFrom(act, [['averagePower'], ['avgPower']])), pickNum(pickFrom(det, [['averagePower'], ['avgPower']]))));\n  assignIfMissing('maxPower', firstValidNumber(pickNum(pickFrom(act, [['maxPower'], ['maximumPower']])), pickNum(pickFrom(det, [['maxPower'], ['maximumPower']]))));\n  assignIfMissing('stamStart', firstValidNumber(pickNum(pickFrom(act, [['startBatteryLevel'], ['startStamina'], ['startingStamina']])), pickNum(pickFrom(det, [['startBatteryLevel'], ['startStamina'], ['startingStamina']]))));\n  assignIfMissing('stamEnd', firstValidNumber(pickNum(pickFrom(act, [['endBatteryLevel'], ['endStamina'], ['endingStamina']])), pickNum(pickFrom(det, [['endBatteryLevel'], ['endStamina'], ['endingStamina']]))));\n\n  return d;\n}\n\n// ============================================================\n// 提示框\n// ============================================================\n\nasync function promptSubjective() {\n  const a = new Alert();\n  a.title = '🧠 主觀感受';\n  a.message = '如果 Garmin Connect 沒有顯示主觀感受，才需要手動輸入。';\n  a.addTextField('感受難度 (1-10)', '3');\n  a.addTextField('感覺如何', '普通');\n  a.addTextField('補給紀錄（可留空）', '');\n  a.addTextField('備註（可留空）', '');\n  a.addAction('✅ 完成');\n  if (await a.present() === -1) {\n    return {\n      difficulty: 'N/A',\n      feeling: 'N/A',\n      nutrition: '',\n      notes: '',\n    };\n  }\n  return {\n    difficulty: a.textFieldValue(0) || 'N/A',\n    feeling:    a.textFieldValue(1) || 'N/A',\n    nutrition:  a.textFieldValue(2) || '',\n    notes:      a.textFieldValue(3) || '',\n  };\n}\n\nfunction parseSubjective(text) {\n  const lines = String(text || '').split('\\n').map(s => s.trim()).filter(Boolean);\n  const clean = function(v) {\n    if (!v) return null;\n    const s = String(v).trim();\n    if (!s || s === '?' || s === '？') return null;\n    return s;\n  };\n\n  const findBefore = function(label) {\n    const idx = lines.findIndex(line => line === label || line.startsWith(label + '：') || line.startsWith(label + ':'));\n    if (idx < 0) return null;\n    if (idx - 1 >= 0) return clean(lines[idx - 1]);\n    return null;\n  };\n\n  const feeling = clean(findBefore('自我評量'));\n  const difficulty = clean(findBefore('感受難度'));\n\n  if (!difficulty && !feeling) return null;\n  return {\n    difficulty: difficulty || 'N/A',\n    feeling: feeling || 'N/A',\n  };\n}\n\nasync function promptWeatherLocation() {\n  const a = new Alert();\n  a.title = '🌤 天氣（可略過）';\n  a.message = '輸入座標或城市名，留空略過';\n  a.addTextField('跑步地點（例: 25.01,121.50 或 台北）', '');\n  a.addAction('查詢天氣');\n  a.addCancelAction('略過');\n  if (await a.present() === -1) return null;\n  return a.textFieldValue(0) || null;\n}\n\n// ============================================================\n// 建立 Markdown\n// ============================================================\n\nfunction buildMarkdown(d, course, subj, weather, laps) {\n  const md = [];\n  const na = 'N/A';\n  const inferredCourseType = course.type || inferCourseType(d.name);\n  const inferredGoal = course.goal || inferGoal(inferredCourseType);\n\n  md.push('# 🏃‍♂️ 跑步訓練分析');\n  md.push('**日期：** ' + d.date + (d.startTime ? ' @ ' + d.startTime : '') +\n          ' ｜ **活動：** ' + (d.name || '跑步'));\n  md.push('');\n\n  // 課表資訊\n  if (inferredCourseType || inferredGoal || course.shoe) {\n    md.push('## 📋 課表資訊');\n    md.push('| 項目 | 內容 |');\n    md.push('|:-----|:-----|');\n    if (inferredCourseType) md.push('| 課表類型 | ' + inferredCourseType + ' |');\n    if (inferredGoal) md.push('| 訓練目的 | ' + inferredGoal + ' |');\n    if (course.shoe) md.push('| 鞋款 | ' + course.shoe + ' |');\n    md.push('');\n  }\n\n  // 天氣環境\n  if (weather) {\n    md.push('## 🌤 天氣環境');\n    md.push('| 項目 | 數值 |');\n    md.push('|:-----|-----:|');\n    md.push('| 天氣描述 | ' + weather.desc + ' |');\n    md.push('| 氣溫 | ' + weather.temp + ' |');\n    md.push('| 濕度 | ' + weather.humidity + ' |');\n    md.push('| 風向 | ' + weather.windDir + ' |');\n    md.push('| 風速 | ' + weather.windKmh + ' |');\n    md.push('');\n  }\n\n  if (subj && (subj.difficulty || subj.feeling)) {\n    md.push('## 🧠 主觀感受');\n    md.push('| 項目 | 內容 |');\n    md.push('|:-----|:-----|');\n    if (subj.difficulty) md.push('| RPE / 感受難度 | ' + subj.difficulty + ' / 10 |');\n    if (subj.feeling) md.push('| 感覺如何 | ' + subj.feeling + ' |');\n    md.push('');\n  }\n\n  // 訓練摘要\n  md.push('## 📊 訓練摘要');\n  md.push('| 項目 | 數值 |');\n  md.push('|:-----|-----:|');\n  md.push('| 距離 | ' + (d.distance != null ? d.distance.toFixed(2) + ' km' : na) + ' |');\n  md.push('| 完成時間 | ' + (d.duration || na) + ' |');\n  md.push('| 移動時間 | ' + (d.movingTime || na) + ' |');\n  md.push('| 平均配速 | ' + (d.avgPace ? d.avgPace + ' /km' : na) + ' |');\n  md.push('| 最佳配速 | ' + (d.bestPace ? d.bestPace + ' /km' : na) + ' |');\n  md.push('| 坡度校正配速 | ' + (d.gap ? d.gap + ' /km' : na) + ' |');\n  md.push('| 平均心率 | ' + (d.avgHR != null ? d.avgHR + ' bpm' : na) + ' |');\n  md.push('| 最大心率 | ' + (d.maxHR != null ? d.maxHR + ' bpm' : na) + ' |');\n  if (course.maxHR && d.avgHR)\n    md.push('| 平均心率% | ' + Math.round(d.avgHR / course.maxHR * 100) + '% |');\n  md.push('| 消耗熱量 | ' + (d.calories != null ? d.calories + ' kcal' : na) + ' |');\n  md.push('| 總爬升 | ' + (d.elevGain != null ? d.elevGain + ' m' : na) + ' |');\n  md.push('| 手錶感測溫度 | ' + (d.watchTemp != null ? d.watchTemp.toFixed(1) + ' °C' : na) + ' |');\n  md.push('');\n\n  // 體力狀態\n  if (d.stamStart != null || d.stamEnd != null) {\n    md.push('## ⚡ 體力狀態');\n    md.push('| 項目 | 數值 |');\n    md.push('|:-----|-----:|');\n    if (d.stamStart != null) md.push('| 起始體力 | ' + d.stamStart + '% |');\n    if (d.stamEnd   != null) md.push('| 結束體力 | ' + d.stamEnd   + '% |');\n    md.push('');\n  }\n\n  // 跑步動態\n  if (d.cadence || d.gct || d.vo) {\n    md.push('## 🦿 跑步動態（Running Economy）');\n    md.push('| 項目 | 數值 |');\n    md.push('|:-----|-----:|');\n    if (d.cadence  != null) md.push('| 平均步頻 | ' + d.cadence + ' spm |');\n    if (d.strideM  != null) md.push('| 平均步幅 | ' + Math.round(d.strideM * 1000) + ' mm |');\n    if (d.gct      != null) md.push('| 平均觸地時間 (GCT) | ' + Math.round(d.gct) + ' ms |');\n    if (d.vo       != null) md.push('| 平均垂直振幅 | ' + Math.round(d.vo * 10) + ' mm |');\n    if (d.vr       != null) md.push('| 平均垂直比 | ' + d.vr.toFixed(1) + '% |');\n    if (d.avgPower != null) md.push('| 平均功率 | ' + d.avgPower + ' W |');\n    if (d.maxPower != null) md.push('| 最大功率 | ' + d.maxPower + ' W |');\n    if (course.cp && d.avgPower)\n      md.push('| 功率% CP | ' + Math.round(d.avgPower / course.cp * 100) + '% |');\n    md.push('');\n  }\n\n  // 訓練效果\n  if (d.teAero != null || d.load != null) {\n    md.push('## 💪 訓練效果');\n    md.push('| 項目 | 數值 |');\n    md.push('|:-----|-----:|');\n    if (d.teBenefit)        md.push('| 主要益處 | ' + d.teBenefit + ' |');\n    if (d.teAero != null)   md.push('| 有氧訓練效果 | ' + d.teAero + ' |');\n    if (d.teAna  != null)   md.push('| 無氧訓練效果 | ' + d.teAna  + ' |');\n    if (d.load   != null)   md.push('| 訓練負荷 | ' + d.load + ' |');\n    if (d.perf   != null)   md.push('| 執行分數 | ' + d.perf + '% |');\n    md.push('');\n  }\n\n  // 每公里數據\n  if (laps && laps.length > 0) {\n    md.push('## 🔢 每公里數據');\n    let hdr = '| 公里 | 配速 | 心率 |';\n    let sep = '|:---:|-----:|-----:|';\n    if (course.maxHR) { hdr += ' 心率% |'; sep += '------:|'; }\n    md.push(hdr);\n    md.push(sep);\n    laps.forEach(function(l) {\n      let row = '| ' + l.km + ' | ' + l.pace + ' | ' + l.hr + ' bpm |';\n      if (course.maxHR) row += ' ' + Math.round(l.hr / course.maxHR * 100) + '% |';\n      md.push(row);\n    });\n    md.push('');\n  }\n\n  md.push('---');\n  md.push('## 💬 分析請求');\n  md.push('請根據以上數據分析這次跑步訓練，包括：');\n  md.push('1. 整體訓練質量評估（依課表目標判斷達成度）');\n  md.push('2. 心率控制表現（與個人最大心率' + (course.maxHR ? ' ' + course.maxHR + ' bpm' : '') + '相比）');\n  md.push('3. 跑步效率解讀（EF、跑步動態、功率）');\n  md.push('4. 訓練效果與累積負荷評估');\n  md.push('5. 下次訓練建議');\n  md.push('');\n  md.push('*CoachOS mRelay · ' + new Date().toLocaleString('zh-TW') + '*');\n\n  return md.join('\\n');\n}\n\n// ============================================================\n// 主程式：依序讀取「數據」與「計圈／間歇訓練」原始 DOM → 合併複製\n// ============================================================\n\nasync function captureTab1(activityId) {\n  const wv = new WebView();\n  await wv.loadURL('https://connect.garmin.com/modern/activity/' + activityId);\n  await wv.present(false);\n  return await wv.evaluateJavaScript(\n    \"document.body ? document.body.innerText.slice(0, 15000) : ''\"\n  );\n}\n\nasync function captureTab2(activityId) {\n  const wv = new WebView();\n  await wv.loadURL('https://connect.garmin.com/modern/activity/' + activityId);\n  await wv.present(false);\n\n  const raw = await wv.evaluateJavaScript(`(() => {\n    const body = document.body ? document.body.innerText : '';\n    const tables = Array.from(document.querySelectorAll('table'))\n      .map(table => table.innerText || '')\n      .filter(text => /平均配速|計圈|間隔/.test(text));\n    return JSON.stringify({ body: body.slice(0, 15000), tables });\n  })()`);\n\n  try {\n    const data = JSON.parse(raw || '{}');\n    const table = Array.isArray(data.tables)\n      ? data.tables\n          .filter(text => /平均配速|計圈|間隔/.test(text))\n          .sort((a, b) => b.length - a.length)[0]\n      : '';\n    return table || data.body || '';\n  } catch (e) {\n    return raw || '';\n  }\n}\n\nasync function main() {\n  try {\n    const intro = new Alert();\n    intro.title = 'CoachOS mRelay';\n    intro.message = '即將開啟 Garmin Connect。請登入（若需要），點進今天的活動，停在「數據」分頁，等內容載入完成後關閉。';\n    intro.addAction('開啟 Garmin');\n    intro.addCancelAction('取消');\n    if (await intro.present() === -1) return;\n\n    // 第一次開啟活動列表，由使用者登入並選取活動。\n    const wv1 = new WebView();\n    await wv1.loadURL('https://connect.garmin.com/app/activities');\n    await wv1.present(false);\n\n    const selectionRaw = await wv1.evaluateJavaScript(`(() => {\n      return JSON.stringify({\n        href: location.href,\n        body: document.body ? document.body.innerText.slice(0, 15000) : ''\n      });\n    })()`);\n    let selection = {};\n    try { selection = JSON.parse(selectionRaw || '{}'); } catch (e) {}\n\n    const activityUrl = String(selection.href || '').trim();\n    const activityId = extractActivityId(activityUrl);\n    if (!activityId) {\n      throw new Error('找不到活動網址，請在第一次關閉前先點進今天的活動頁');\n    }\n\n    const tab1 = selection.body || '';\n    if (!tab1 || tab1.length < 100) {\n      throw new Error('無法讀取「數據」分頁，請確認活動頁已完整載入再關閉');\n    }\n\n    const guide = new Alert();\n    guide.title = '數據分頁已完成';\n    guide.message = '接下來會再次開啟同一活動頁。請切換到「計圈」或「間歇訓練」分頁後再關閉。\\n\\n請不要選第三個「區段」分頁。';\n    guide.addAction('開啟計圈／間歇訓練');\n    await guide.present();\n\n    // 第二次開啟同一活動頁，Tab 名稱不固定，以表格內容判斷。\n    const wv2 = new WebView();\n    await wv2.loadURL(activityUrl);\n    await wv2.present(false);\n    const tab2Raw = await wv2.evaluateJavaScript(`(() => {\n      const body = document.body ? document.body.innerText : '';\n      const tables = Array.from(document.querySelectorAll('table'))\n        .map(table => table.innerText || '')\n        .filter(text => /平均配速|計圈|間隔/.test(text));\n      return JSON.stringify({ body: body.slice(0, 15000), tables });\n    })()`);\n\n    let tab2 = '';\n    try {\n      const data = JSON.parse(tab2Raw || '{}');\n      const table = Array.isArray(data.tables)\n        ? data.tables\n            .filter(text => /平均配速|計圈|間隔/.test(text))\n            .sort((a, b) => b.length - a.length)[0]\n        : '';\n      tab2 = table || data.body || '';\n    } catch (e) {\n      tab2 = tab2Raw || '';\n    }\n    if (!tab2 || tab2.length < 100) {\n      throw new Error('無法讀取「計圈／間歇訓練」分頁，請切換到該分頁後再關閉');\n    }\n\n    const output = [\n      '# CoachOS mRelay Garmin Raw Activity',\n      '**活動網址：** ' + activityUrl,\n      '',\n      '請直接根據以下 Garmin Connect 原始內容分析，不要假設缺失欄位，也不要把欄位位置當成固定格式。',\n      '日期判讀規則：Garmin 會將今天顯示為「今天」、昨天顯示為「昨天」、同一週較早活動顯示為星期幾，更早活動才顯示完整日期；請依本次執行日期還原實際日期。',\n      '',\n      '## 數據分頁原始 DOM',\n      '```text',\n      tab1,\n      '```',\n      '',\n      '## 計圈／間歇訓練分頁原始 DOM',\n      '```text',\n      tab2,\n      '```',\n    ].join('\\n');\n    Pasteboard.copyString(output);\n\n    const done = new Alert();\n    done.title = '✅ CoachOS mRelay 完成';\n    done.message = '「數據」與「計圈／間歇訓練」分頁原始內容已複製到剪貼簿。\\n\\n接下來請開啟你常用的 AI，例如 ChatGPT、Claude 或 Gemini，進入要使用的 Project／對話，再貼上內容進行分析。';\n    done.addAction('👌 好的');\n    await done.present();\n\n  } catch(e) {\n    const err = new Alert();\n    err.title = '❌ 錯誤';\n    err.message = String(e) + (e.stack ? '\\n\\n' + e.stack.slice(0, 300) : '');\n    err.addAction('OK');\n    await err.present();\n  }\n}\n\nmain();\n";

const ANDROID_01_BASE64 = "";
